text:
  &.minimized .account-hub-view {
    display: none;
  }
}

#accountHubPlaceholder:not([hidden]) {
  position: absolute;
  z-index: 9;
  inset-inline-end: 9px;
  inset-block-end: 9px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 15px;
  border: 1px solid var(--selected-item-color);
  border-radius: var(--button-border-radius);
  color: var(--layout-color-2);
  background-color: var(--layout-background-1);
  box-shadow: 0 2px 4px rgba(58, 57, 68, 0.3);

  & span {
    font-size: 1.15rem;
    font-weight: 400;
  }

  &:hover {
    background-color: var(--layout-background-2);
    color: var(--selected-item-color);

    &:active {
      background-color: var(--layout-background-3);
    }
  }

  @media (prefers-contrast) {
    &:hover,
    &:hover:active {
      background-color: SelectedItem;
      color: SelectedItemText;
    }
  }
}
